"""
Dependency Vulnerability Scanner
Checks project dependencies for known vulnerabilities
"""

import json
import requests
import re
from pathlib import Path
from packaging import version

class DependencyScanner:
    def __init__(self):
        self.vulnerability_db = self.load_vulnerability_db()
        self.vulnerabilities_found = []

    def load_vulnerability_db(self):
        """Load vulnerability database (simplified example)"""
        # In production, this would fetch from NVD, GitHub Advisories, etc.
        return {
            "requests": [
                {"version": "<2.25.0", "cve": "CVE-2021-33503", "severity": "HIGH", "description": "HTTP header injection"},
                {"version": "<2.28.0", "cve": "CVE-2023-32681", "severity": "MEDIUM", "description": "Information disclosure"}
            ],
            "django": [
                {"version": "<3.2.9", "cve": "CVE-2021-33203", "severity": "HIGH", "description": "SQL injection"},
                {"version": "<4.0.3", "cve": "CVE-2022-28346", "severity": "MEDIUM", "description": "XSS vulnerability"}
            ],
            "flask": [
                {"version": "<2.0.3", "cve": "CVE-2022-29361", "severity": "MEDIUM", "description": "Open redirect"}
            ],
            "numpy": [
                {"version": "<1.22.0", "cve": "CVE-2021-41495", "severity": "HIGH", "description": "Buffer overflow"}
            ]
        }

    def parse_requirements_txt(self, filepath):
        """Parse Python requirements.txt file"""
        dependencies = {}

        try:
            with open(filepath, 'r') as f:
                for line in f:
                    line = line.strip()
                    if line and not line.startswith('#'):
                        # Parse package name and version
                        match = re.match(r'([a-zA-Z0-9\-_\[\]]+)([=<>!~]=?[^\s]+)?', line)
                        if match:
                            package = match.group(1).split('[')[0]  # Remove extras
                            version_spec = match.group(2) if match.group(2) else "latest"
                            dependencies[package.lower()] = {"spec": version_spec, "file": str(filepath)}
        except Exception as e:
            print(f"Error parsing {filepath}: {e}")

        return dependencies

    def parse_package_json(self, filepath):
        """Parse Node.js package.json file"""
        dependencies = {}

        try:
            with open(filepath, 'r') as f:
                data = json.load(f)

                # Check dependencies and devDependencies
                for dep_type in ['dependencies', 'devDependencies', 'peerDependencies']:
                    if dep_type in data:
                        for package, version_spec in data[dep_type].items():
                            dependencies[package.lower()] = {
                                "spec": version_spec,
                                "file": str(filepath),
                                "type": dep_type
                            }
        except Exception as e:
            print(f"Error parsing {filepath}: {e}")

        return dependencies

    def check_vulnerabilities(self, dependencies):
        """Check dependencies against vulnerability database"""
        for package, info in dependencies.items():
            if package in self.vulnerability_db:
                package_vulns = self.vulnerability_db[package]

                for vuln in package_vulns:
                    # Simplified version check (in reality, use proper version comparison)
                    version_spec = info["spec"]
                    vuln_version = vuln["version"]

                    # Check if version is vulnerable
                    # Note: This is a simplified check. Real implementation would use proper version comparison
                    if version_spec != "latest":
                        # Extract version number from spec
                        version_match = re.search(r'[0-9]+\.[0-9]+\.[0-9]+', version_spec)
                        if version_match:
                            installed_version = version_match.group()

                            # Check if version matches vulnerable range
                            # This is a simplified check - real implementation would parse version constraints
                            if vuln_version.startswith("<") and installed_version < vuln_version[1:]:
                                self.vulnerabilities_found.append({
                                    "package": package,
                                    "installed_version": installed_version,
                                    "vulnerable_version": vuln_version,
                                    "severity": vuln["severity"],
                                    "cve": vuln["cve"],
                                    "description": vuln["description"],
                                    "file": info["file"]
                                })

    def scan_project(self, project_path):
        """Scan a project for vulnerable dependencies"""
        project_path = Path(project_path)
        all_dependencies = {}

        # Look for dependency files
        dependency_files = [
            ("requirements.txt", self.parse_requirements_txt),
            ("package.json", self.parse_package_json),
            ("Pipfile", self.parse_pipfile),  # Would need implementation
            ("poetry.lock", self.parse_poetry_lock),  # Would need implementation
            ("pom.xml", self.parse_pom_xml),  # Would need implementation
            ("build.gradle", self.parse_gradle)  # Would need implementation
        ]

        for filename, parser in dependency_files:
            filepath = project_path / filename
            if filepath.exists():
                print(f"Found {filename}")
                dependencies = parser(filepath)
                all_dependencies.update(dependencies)

        # Check for vulnerabilities
        self.check_vulnerabilities(all_dependencies)

        return self.generate_report()

    def generate_report(self):
        """Generate vulnerability report"""
        report = {
            "summary": {
                "total_dependencies": len(self.vulnerabilities_found),
                "high_severity": sum(1 for v in self.vulnerabilities_found if v["severity"] == "HIGH"),
                "medium_severity": sum(1 for v in self.vulnerabilities_found if v["severity"] == "MEDIUM"),
                "low_severity": sum(1 for v in self.vulnerabilities_found if v["severity"] == "LOW")
            },
            "vulnerabilities": self.vulnerabilities_found,
            "recommendations": [
                "Update vulnerable packages to latest secure versions",
                "Regularly run dependency scanning in CI/CD",
                "Consider using dependabot or similar tools for automatic updates"
            ]
        }
        return report

# Example usage
if __name__ == "__main__":
    scanner = DependencyScanner()

    # Scan current directory
    report = scanner.scan_project(".")

    print("\n=== Dependency Vulnerability Scan Report ===")
    print(f"Total vulnerabilities found: {report['summary']['total_dependencies']}")
    print(f"High severity: {report['summary']['high_severity']}")
    print(f"Medium severity: {report['summary']['medium_severity']}")
    print(f"Low severity: {report['summary']['low_severity']}")

