import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Badge } from './ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from './ui/tabs';
import { Alert, AlertDescription } from './ui/alert';
import { Progress } from './ui/progress';

const TestDashboard = () => {
  const [testData, setTestData] = useState(null);
  const [trendData, setTrendData] = useState([]);
  const [realtimeUpdates, setRealtimeUpdates] = useState([]);
  const [selectedTimeRange, setSelectedTimeRange] = useState('24h');

  // Colors for charts
  const COLORS = ['#10B981', '#EF4444', '#F59E0B', '#8B5CF6'];

  // Fetch initial data
  useEffect(() => {
    fetchTestData();
    fetchTrendData();

    // Set up WebSocket for real-time updates
    const ws = new WebSocket('ws://localhost:8080/ws/test-updates');

    ws.onmessage = (event) => {
      const update = JSON.parse(event.data);
      setRealtimeUpdates(prev => [update, ...prev.slice(0, 9)]); // Keep last 10

      if (update.type === 'TEST_COMPLETE') {
        // Update test data with new result
        updateTestData(update.data);
      }
    };

    return () => ws.close();
  }, []);

  const fetchTestData = async () => {
    try {
      const response = await fetch('/api/test-results/summary');
      const data = await response.json();
      setTestData(data);
    } catch (error) {
      console.error('Error fetching test data:', error);
    }
  };

  const fetchTrendData = async () => {
    try {
      const response = await fetch(`/api/test-results/trend?range=${selectedTimeRange}`);
      const data = await response.json();
      setTrendData(data);
    } catch (error) {
      console.error('Error fetching trend data:', error);
    }
  };

  const updateTestData = (newResult) => {
    setTestData(prev => ({
      ...prev,
      total: prev.total + 1,
      passed: newResult.status === 'PASSED' ? prev.passed + 1 : prev.passed,
      failed: newResult.status === 'FAILED' ? prev.failed + 1 : prev.failed,
      skipped: newResult.status === 'SKIPPED' ? prev.skipped + 1 : prev.skipped,
      passPercentage: ((prev.passed + (newResult.status === 'PASSED' ? 1 : 0)) / 
                     (prev.total + 1) * 100).toFixed(1)
    }));
  };

  // Calculate metrics
  const calculateMetrics = () => {
    if (!testData) return {};

    return {
      testEffectiveness: ((testData.passed + testData.failed) / testData.total * 100).toFixed(1),
      defectDensity: (testData.failed / testData.total * 1000).toFixed(2), // per 1000 tests
      avgTestDuration: (testData.totalDuration / testData.total).toFixed(2),
      stabilityScore: calculateStabilityScore()
    };
  };

  const calculateStabilityScore = () => {
    // Calculate stability based on recent failures and flaky tests
    const recentFailures = trendData.slice(-10).reduce((sum, day) => sum + day.failed, 0);
    const totalRecentTests = trendData.slice(-10).reduce((sum, day) => sum + day.total, 0);

    if (totalRecentTests === 0) return 100;

    const failureRate = (recentFailures / totalRecentTests) * 100;
    return Math.max(0, 100 - failureRate * 2).toFixed(1);
  };

  // Prepare data for charts
  const prepareCategoryData = () => {
    if (!testData?.categories) return [];

    return Object.entries(testData.categories).map(([name, data]) => ({
      name,
      passed: data.passed,
      failed: data.failed,
      total: data.total,
      passRate: ((data.passed / data.total) * 100).toFixed(1)
    }));
  };

  const prepareStatusData = () => {
    if (!testData) return [];

    return [
      { name: 'Passed', value: testData.passed, color: COLORS[0] },
      { name: 'Failed', value: testData.failed, color: COLORS[1] },
      { name: 'Skipped', value: testData.skipped, color: COLORS[2] },
      { name: 'Error', value: testData.errors, color: COLORS[3] }
    ].filter(item => item.value > 0);
  };

  const metrics = calculateMetrics();
  const categoryData = prepareCategoryData();
  const statusData = prepareStatusData();

  if (!testData) {
    return <div>Loading dashboard...</div>;
  }

  return (
    <div className="container mx-auto p-6">
      <h1 className="text-3xl font-bold mb-6">🧪 Test Analytics Dashboard</h1>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
        <Card>
          <CardHeader>
            <CardTitle className="text-sm font-medium text-gray-500">Total Tests</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-3xl font-bold">{testData.total}</div>
            <div className="text-sm text-gray-500">Last 24h: +{testData.recentTests || 0}</div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="text-sm font-medium text-gray-500">Pass Rate</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-3xl font-bold text-green-600">
              {testData.passPercentage}%
            </div>
            <Progress value={parseFloat(testData.passPercentage)} className="mt-2" />
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="text-sm font-medium text-gray-500">Stability Score</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-3xl font-bold">{metrics.stabilityScore}</div>
            <div className="text-sm text-gray-500">/100</div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="text-sm font-medium text-gray-500">Avg Duration</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-3xl font-bold">{metrics.avgTestDuration}s</div>
            <div className="text-sm text-gray-500">per test</div>
          </CardContent>
        </Card>
      </div>

      {/* Charts Section */}
      <Tabs defaultValue="overview" className="mb-6">
        <TabsList>
          <TabsTrigger value="overview">Overview</TabsTrigger>
          <TabsTrigger value="trends">Trends</TabsTrigger>
          <TabsTrigger value="categories">Categories</TabsTrigger>
          <TabsTrigger value="realtime">Real-time</TabsTrigger>
        </TabsList>

        <TabsContent value="overview">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {/* Trend Chart */}
            <Card>
              <CardHeader>
                <CardTitle>Test Results Trend</CardTitle>
              </CardHeader>
              <CardContent>
                <ResponsiveContainer width="100%" height={300}>
                  <LineChart data={trendData}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="date" />
                    <YAxis />
                    <Tooltip />
                    <Legend />
                    <Line type="monotone" dataKey="passed" stroke="#10B981" name="Passed" />
                    <Line type="monotone" dataKey="failed" stroke="#EF4444" name="Failed" />
                    <Line type="monotone" dataKey="passRate" stroke="#3B82F6" name="Pass Rate" />
                  </LineChart>
                </ResponsiveContainer>
              </CardContent>
            </Card>

            {/* Status Distribution */}
            <Card>
              <CardHeader>
                <CardTitle>Test Status Distribution</CardTitle>
              </CardHeader>
              <CardContent>
                <ResponsiveContainer width="100%" height={300}>
                  <PieChart>
                    <Pie
                      data={statusData}
                      cx="50%"
                      cy="50%"
                      labelLine={false}
                      label={({ name, percent }) => `${name}: ${(percent * 100).toFixed(0)}%`}
                      outerRadius={80}
                      fill="#8884d8"
                      dataKey="value"
                    >
                      {statusData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color} />
                      ))}
                    </Pie>
                    <Tooltip formatter={(value) => [value, 'Tests']} />
                  </PieChart>
                </ResponsiveContainer>
              </CardContent>
            </Card>
          </div>
        </TabsContent>

        <TabsContent value="categories">
          <Card>
            <CardHeader>
              <CardTitle>Category Performance</CardTitle>
            </CardHeader>
            <CardContent>
              <ResponsiveContainer width="100%" height={400}>
                <BarChart data={categoryData}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="name" />
                  <YAxis yAxisId="left" orientation="left" stroke="#8884d8" />
                  <YAxis yAxisId="right" orientation="right" stroke="#82ca9d" />
                  <Tooltip />
                  <Legend />
                  <Bar yAxisId="left" dataKey="passed" fill="#10B981" name="Passed" />
                  <Bar yAxisId="left" dataKey="failed" fill="#EF4444" name="Failed" />
                  <Line yAxisId="right" type="monotone" dataKey="passRate" stroke="#3B82F6" name="Pass Rate" />
                </BarChart>
              </ResponsiveContainer>

              {/* Category Details Table */}
              <div className="mt-6">
                <h3 className="text-lg font-semibold mb-3">Category Details</h3>
                <div className="overflow-x-auto">
                  <table className="min-w-full divide-y divide-gray-200">
                    <thead>
                      <tr>
                        <th className="px-4 py-2 text-left">Category</th>
                        <th className="px-4 py-2 text-left">Total Tests</th>
                        <th className="px-4 py-2 text-left">Passed</th>
                        <th className="px-4 py-2 text-left">Failed</th>
                        <th className="px-4 py-2 text-left">Pass Rate</th>
                      </tr>
                    </thead>
                    <tbody>
                      {categoryData.map((category) => (
                        <tr key={category.name}>
                          <td className="px-4 py-2">{category.name}</td>
                          <td className="px-4 py-2">{category.total}</td>
                          <td className="px-4 py-2">{category.passed}</td>
                          <td className="px-4 py-2">{category.failed}</td>
                          <td className="px-4 py-2">
                            <Badge variant={category.passRate >= 90 ? 'success' : 
                                           category.passRate >= 80 ? 'warning' : 'destructive'}>
                              {category.passRate}%
                            </Badge>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="realtime">
          <Card>
            <CardHeader>
              <CardTitle>Real-time Test Updates</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {realtimeUpdates.length === 0 ? (
                  <div className="text-center text-gray-500 py-8">
                    Waiting for test updates...
                  </div>
                ) : (
                  realtimeUpdates.map((update, index) => (
                    <Alert 
                      key={index} 
                      variant={update.status === 'PASSED' ? 'default' : 'destructive'}
                    >
                      <AlertDescription>
                        <div className="flex justify-between">
                          <span>
                            <strong>{update.testName}</strong> - {update.module}
                          </span>
                          <Badge variant={update.status === 'PASSED' ? 'success' : 'destructive'}>
                            {update.status}
                          </Badge>
                        </div>
                        <div className="text-sm text-gray-600 mt-1">
                          Duration: {update.duration}s | {new Date(update.timestamp).toLocaleTimeString()}
                        </div>
                        {update.error && (
                          <div className="mt-2 text-sm font-mono bg-gray-100 p-2 rounded">
                            {update.error}
                          </div>
                        )}
                      </AlertDescription>
                    </Alert>
                  ))
                )}
              </div>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* Metrics Summary */}
      <Card className="mt-6">
        <CardHeader>
          <CardTitle>Quality Metrics</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <h4 className="text-sm font-medium text-gray-500">Test Effectiveness</h4>
              <div className="text-2xl font-bold mt-1">{metrics.testEffectiveness}%</div>
              <p className="text-sm text-gray-500">Percentage of tests that provide meaningful results</p>
            </div>
            <div>
              <h4 className="text-sm font-medium text-gray-500">Defect Density</h4>
              <div className="text-2xl font-bold mt-1">{metrics.defectDensity}</div>
              <p className="text-sm text-gray-500">Defects per 1000 test executions</p>
            </div>
            <div>
              <h4 className="text-sm font-medium text-gray-500">Predicted Quality Trend</h4>
              <div className="text-2xl font-bold mt-1">
                {trendData.length >= 2 ? (
                  trendData[trendData.length - 1].passRate > trendData[trendData.length - 2].passRate 
                    ? '↗ Improving' 
                    : '↘ Declining'
                ) : '→ Stable'}
              </div>
              <p className="text-sm text-gray-500">Based on 7-day trend analysis</p>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

export default TestDashboard;

