pipeline {
    agent any

    environment {
        TEST_ENV = 'integration'
        BROWSER = 'chrome-headless'
        PARALLEL_COUNT = 3
    }

    stages {
        stage('Checkout & Setup') {
            steps {
                checkout scm
                sh 'npm ci'
            }
        }

        stage('Unit Tests') {
            steps {
                sh 'npm test -- --coverage'
            }
            post {
                always {
                    junit 'reports/junit/*.xml'
                    publishHTML(target: [
                        reportDir: 'coverage/lcov-report',
                        reportFiles: 'index.html',
                        reportName: 'Code Coverage'
                    ])
                }
            }
        }

        stage('Integration Tests') {
            parallel {
                stage('API Tests') {
                    steps {
                        sh 'npm run test:api'
                    }
                }
                stage('Component Tests') {
                    steps {
                        sh 'npm run test:component'
                    }
                }
            }
            post {
                always {
                    junit 'reports/**/*.xml'
                    archiveArtifacts 'reports/screenshots/*.png'
                }
            }
        }

        stage('Quality Gate') {
            steps {
                script {
                    def testResults = readJSON file: 'reports/summary.json'
                    if (testResults.passRate < 95) {
                        error "Quality gate failed: Pass rate ${testResults.passRate}% < 95%"
                    }
                    if (testResults.coverage < 80) {
                        error "Quality gate failed: Coverage ${testResults.coverage}% < 80%"
                    }
                }
            }
        }

        stage('Deploy to Staging') {
            when {
                expression { currentBuild.result == null || currentBuild.result == 'SUCCESS' }
            }
            steps {
                sh 'kubectl apply -f k8s/staging/'
            }
        }
    }

    post {
        always {
            emailext(
                subject: "${env.JOB_NAME} - Build #${env.BUILD_NUMBER} - ${currentBuild.result}",
                body: '''Check console output at ${BUILD_URL}console''',
                to: 'team@example.com'
            )
        }
        failure {
            slackSend(
                channel: '#build-failures',
                message: "Build ${env.JOB_NAME} #${env.BUILD_NUMBER} failed: ${env.BUILD_URL}"
            )
        }
    }
}

