import ast
import astor
from typing import List, Dict, Any
import re

class TestRefactoringAssistant:
    """
    Automated analysis and refactoring recommendations for test code
    """

    def __init__(self):
        self.smell_patterns = {
            'hardcoded_values': r'("|\')(?!test|example)[A-Za-z0-9_]+(\"|\')',
            'magic_numbers': r'\b\d{3,}\b',
            'long_methods': r'def .*:\n(?:.*\n){20,}',
            'duplicate_code': None,  # Would use more complex detection
            'sleep_calls': r'Thread\.sleep|time\.sleep'
        }

    def analyze_test_file(self, file_path: str) -> Dict[str, Any]:
        """Analyze test file for refactoring opportunities"""
        with open(file_path, 'r') as f:
            content = f.read()

        analysis = {
            'file_path': file_path,
            'smells': [],
            'complexity_score': 0,
            'maintenance_risk': 0,
            'recommendations': []
        }

        # Parse AST for structural analysis
        try:
            tree = ast.parse(content)
            analysis.update(self._analyze_ast(tree))
        except SyntaxError:
            analysis['parse_error'] = True

        # Pattern-based smell detection
        analysis['smells'] = self._detect_code_smells(content)

        # Calculate scores
        analysis['complexity_score'] = self._calculate_complexity(tree)
        analysis['maintenance_risk'] = self._calculate_maintenance_risk(analysis)

        # Generate recommendations
        analysis['recommendations'] = self._generate_recommendations(analysis)

        return analysis

    def _analyze_ast(self, tree: ast.AST) -> Dict[str, Any]:
        """Analyze Abstract Syntax Tree"""
        stats = {
            'total_lines': 0,
            'function_count': 0,
            'class_count': 0,
            'import_count': 0,
            'assert_count': 0,
            'test_method_count': 0
        }

        for node in ast.walk(tree):
            if isinstance(node, ast.FunctionDef):
                stats['function_count'] += 1
                if node.name.startswith('test_'):
                    stats['test_method_count'] += 1
                    # Check for AAA pattern
                    stats[f'test_{node.name}_has_aaa'] = self._check_aaa_pattern(node)
            elif isinstance(node, ast.ClassDef):
                stats['class_count'] += 1
            elif isinstance(node, ast.Import) or isinstance(node, ast.ImportFrom):
                stats['import_count'] += 1
            elif isinstance(node, ast.Assert):
                stats['assert_count'] += 1

        return stats

    def _check_aaa_pattern(self, function_node: ast.FunctionDef) -> bool:
        """Check if test follows Arrange-Act-Assert pattern"""
        # Simplified check - real implementation would be more sophisticated
        body_str = astor.to_source(function_node)
        has_comment_sections = ('# Arrange' in body_str and 
                               '# Act' in body_str and 
                               '# Assert' in body_str)
        return has_comment_sections

    def _detect_code_smells(self, content: str) -> List[Dict]:
        """Detect code smells using pattern matching"""
        smells = []

        for smell_type, pattern in self.smell_patterns.items():
            if pattern:
                matches = re.finditer(pattern, content)
                for match in matches:
                    line_num = content[:match.start()].count('\n') + 1
                    smells.append({
                        'type': smell_type,
                        'line': line_num,
                        'snippet': match.group(),
                        'severity': self._get_smell_severity(smell_type)
                    })

        return smells

    def _get_smell_severity(self, smell_type: str) -> str:
        """Get severity level for code smell"""
        severity_map = {
            'sleep_calls': 'HIGH',
            'hardcoded_values': 'MEDIUM',
            'magic_numbers': 'LOW',
            'long_methods': 'MEDIUM',
            'duplicate_code': 'HIGH'
        }
        return severity_map.get(smell_type, 'LOW')

    def _calculate_complexity(self, tree: ast.AST) -> float:
        """Calculate cyclomatic complexity (simplified)"""
        complexity = 1  # Start with 1

        for node in ast.walk(tree):
            if isinstance(node, (ast.If, ast.While, ast.For, 
                               ast.And, ast.Or, ast.Assert)):
                complexity += 1
            elif isinstance(node, ast.Try):
                complexity += len(node.handlers)
                if node.finalbody:
                    complexity += 1

        return complexity

    def _calculate_maintenance_risk(self, analysis: Dict) -> float:
        """Calculate maintenance risk score"""
        risk = 0

        # Add risk based on smells
        for smell in analysis.get('smells', []):
            if smell['severity'] == 'HIGH':
                risk += 3
            elif smell['severity'] == 'MEDIUM':
                risk += 2
            else:
                risk += 1

        # Add risk based on complexity
        if analysis.get('complexity_score', 0) > 20:
            risk += 5
        elif analysis.get('complexity_score', 0) > 10:
            risk += 3

        # Add risk based on length
        if analysis.get('function_count', 0) > 10:
            risk += 2

        return risk / 20  # Normalize to 0-1 range

    def _generate_recommendations(self, analysis: Dict) -> List[Dict]:
        """Generate refactoring recommendations"""
        recommendations = []

        # Recommendations based on smells
        for smell in analysis.get('smells', []):
            rec = {
                'type': 'CODE_SMELL',
                'description': f"Found {smell['type']} at line {smell['line']}",
                'action': self._get_smell_recommendation(smell['type']),
                'priority': 'HIGH' if smell['severity'] == 'HIGH' else 'MEDIUM',
                'estimated_effort': 'SMALL'
            }
            recommendations.append(rec)

        # Complexity recommendations
        if analysis.get('complexity_score', 0) > 15:
            recommendations.append({
                'type': 'COMPLEXITY',
                'description': f"High cyclomatic complexity: {analysis['complexity_score']}",
                'action': 'Consider extracting helper methods or breaking into smaller tests',
                'priority': 'MEDIUM',
                'estimated_effort': 'MEDIUM'
            })

        return recommendations

    def _get_smell_recommendation(self, smell_type: str) -> str:
        """Get recommendation for specific code smell"""
        recommendations = {
            'hardcoded_values': 'Extract to constants or configuration',
            'magic_numbers': 'Replace with named constants',
            'sleep_calls': 'Replace with explicit waits or polling',
            'long_methods': 'Break into smaller focused methods',
            'duplicate_code': 'Extract common logic to helper methods'
        }
        return recommendations.get(smell_type, 'Review and refactor')

# Usage example
if __name__ == "__main__":
    assistant = TestRefactoringAssistant()

    # Analyze a test file
    analysis = assistant.analyze_test_file("sample_test.py")

    print(f"Maintenance Risk Score: {analysis['maintenance_risk']:.2f}")
    print(f"Code Smells Found: {len(analysis['smells'])}")
    print("\nRecommendations:")
    for rec in analysis['recommendations']:
        print(f"- [{rec['priority']}] {rec['description']}")
        print(f"  Action: {rec['action']}\n")

import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.chrome.ChromeOptions;
import org.openqa.selenium.firefox.FirefoxDriver;
import org.openqa.selenium.firefox.FirefoxOptions;
import org.openqa.selenium.edge.EdgeDriver;
import org.openqa.selenium.remote.RemoteWebDriver;
import java.net.URL;
import java.time.Duration;

public class WebDriverSetup {

    // Local Chrome setup
    public static WebDriver setupChrome() {
        // Selenium 4+ - Automatic driver management
        ChromeOptions options = new ChromeOptions();

        // Common options for stability
        options.addArguments("--no-sandbox");
        options.addArguments("--disable-dev-shm-usage");
        options.addArguments("--disable-gpu");
        options.addArguments("--window-size=1920,1080");

        // Headless option for CI/CD
        if (System.getenv("CI") != null) {
            options.addArguments("--headless=new");
        }

        // Set preferences
        options.addArguments("--disable-notifications");
        options.addArguments("--disable-popup-blocking");

        WebDriver driver = new ChromeDriver(options);

        // Configure timeouts
        driver.manage().timeouts().implicitlyWait(Duration.ofSeconds(10));
        driver.manage().timeouts().pageLoadTimeout(Duration.ofSeconds(30));
        driver.manage().timeouts().scriptTimeout(Duration.ofSeconds(30));

        // Window management
        driver.manage().window().maximize();

        return driver;
    }

    // Remote WebDriver setup (Selenium Grid/Docker)
    public static WebDriver setupRemote() throws Exception {
        ChromeOptions options = new ChromeOptions();

        // Add capabilities
        options.setCapability("browserName", "chrome");
        options.setCapability("browserVersion", "latest");
        options.setCapability("platformName", "linux");

        // Connect to Selenium Grid
        URL gridUrl = new URL("http://localhost:4444");
        WebDriver driver = new RemoteWebDriver(gridUrl, options);

        return driver;
    }

    // Firefox setup
    public static WebDriver setupFirefox() {
        FirefoxOptions options = new FirefoxOptions();

        // Firefox specific options
        options.addArguments("--width=1920");
        options.addArguments("--height=1080");

        // Headless mode
        if (System.getenv("CI") != null) {
            options.addArguments("--headless");
        }

        // Set preferences
        options.addPreference("dom.webnotifications.enabled", false);

        WebDriver driver = new FirefoxDriver(options);
        return driver;
    }

    // Edge setup
    public static WebDriver setupEdge() {
        // Edge automatically uses Microsoft WebDriver
        WebDriver driver = new EdgeDriver();
        return driver;
    }
}

