        // Contains attribute
        // return driver.findElement(By.xpath("//div[contains(@class, 'active')]"));

        // Position based
        // return driver.findElement(By.xpath("(//table//tr)[3]"));

        // Multiple conditions
        // return driver.findElement(By.xpath("//input[@type='text' and @name='username']"));
    }

    // 8. Finding multiple elements
    public void handleMultipleElements() {
        // Get all elements matching criteria
        List<WebElement> buttons = driver.findElements(By.cssSelector("button"));

