  const isSorted = values.every((val, i, arr) => {
    if (i === 0) return true
    return order === 'asc' ? val >= arr[i - 1] : val <= arr[i - 1]
  })

  expect(isSorted, `Expected values to be sorted in ${order} order`).to.be.true

  return subject
})

