// cypress/support/pageObjects/LoginPage.js
export default class LoginPage {
  elements = {
    emailInput: () => cy.get('[data-test="email-input"]'),
    passwordInput: () => cy.get('[data-test="password-input"]'),
    submitButton: () => cy.get('[data-test="submit-button"]'),
    emailError: () => cy.get('[data-test="email-error"]'),
    passwordError: () => cy.get('[data-test="password-error"]'),
    toast: () => cy.get('[role="alert"]'),
    rateLimitMessage: () => cy.get('[data-test="rate-limit-message"]')
  }

  visit() {
    cy.visit('/login')
    return this
  }

  login(credentials) {
    const { email, password } = credentials

    this.elements.emailInput().clear().type(email)
    this.elements.passwordInput().clear().type(password)
    this.elements.submitButton().click()

    return this
  }

  submitForm() {
    this.elements.submitButton().click()
    return this
  }

  assertLoggedIn() {
    cy.url().should('include', '/dashboard')
    cy.getCookie('session_id').should('exist')
    return this
  }

  assertValidationError(field, expectedMessage) {
    this.elements[`${field}Error`]()
      .should('be.visible')
      .and('contain', expectedMessage)
    return this
  }
}

