// cypress/plugins/index.js
const fs = require('fs')
const path = require('path')

module.exports = (on, config) => {
  on('after:run', (results) => {
    // Generate custom HTML report
    const reportDir = path.join(__dirname, '../reports')
    if (!fs.existsSync(reportDir)) {
      fs.mkdirSync(reportDir, { recursive: true })
    }

    const reportPath = path.join(reportDir, 'custom-report.html')
    const html = generateCustomReport(results)
    fs.writeFileSync(reportPath, html)

    // Send summary to console
    console.log('\n=== Test Execution Summary ===')
    console.log(`Total Tests: ${results.totalTests}`)
    console.log(`Passed: ${results.totalPassed}`)
    console.log(`Failed: ${results.totalFailed}`)
    console.log(`Pending: ${results.totalPending}`)
    console.log(`Duration: ${results.totalDuration}ms`)
    console.log(`Report: ${reportPath}`)

    // Upload to external service if needed
    if (process.env.TEST_REPORT_SERVICE_URL) {
      uploadReport(results)
    }
  })
}

function generateCustomReport(results) {
  return `
  <!DOCTYPE html>
  <html>
  <head>
    <title>Cypress Test Report</title>
    <style>
      body { font-family: Arial, sans-serif; margin: 20px; }
      .summary { background: #f5f5f5; padding: 20px; border-radius: 5px; }
      .passed { color: green; }
      .failed { color: red; }
      .pending { color: orange; }
      table { width: 100%; border-collapse: collapse; }
      th, td { padding: 10px; text-align: left; border-bottom: 1px solid #ddd; }
      .test-row:hover { background: #f9f9f9; }
    </style>
  </head>
  <body>
    <h1>Cypress Test Report</h1>
    <div class="summary">
      <h2>Summary</h2>
      <p>Total Tests: ${results.totalTests}</p>
      <p class="passed">Passed: ${results.totalPassed}</p>
      <p class="failed">Failed: ${results.totalFailed}</p>
      <p class="pending">Pending: ${results.totalPending}</p>
      <p>Duration: ${results.totalDuration}ms</p>
    </div>
    <h2>Test Details</h2>
    <table>
      <thead>
        <tr>
          <th>Test</th>
          <th>Status</th>
          <th>Duration</th>
          <th>Screenshot</th>
        </tr>
      </thead>
      <tbody>
        ${generateTestRows(results.runs)}
      </tbody>
    </table>
  </body>
  </html>
  `
}

function generateTestRows(runs) {
  return runs.flatMap(run => 
    run.tests.map(test => `
      <tr class="test-row">
        <td>${test.title.join(' › ')}</td>
        <td class="${test.state}">${test.state}</td>
        <td>${test.duration}ms</td>
        <td>${test.screenshot ? '<a href="' + test.screenshot + '">View</a>' : 'N/A'}</td>
      </tr>
    `).join('')
  ).join('')
}

