// custom-reporter.js
class CustomReporter {
  constructor(options) {
    this.options = options;
    this.results = [];
  }

  onBegin(config, suite) {
    console.log(`Starting test run with ${suite.allTests().length} tests`);
    this.startTime = Date.now();
  }

  onTestBegin(test) {
    console.log(`Starting test: ${test.title}`);
  }

  onTestEnd(test, result) {
    this.results.push({
      test: test.title,
      status: result.status,
      duration: result.duration,
      errors: result.errors
    });

    const statusIcon = {
      passed: '✅',
      failed: '❌',
      skipped: '⏭️',
      timedOut: '⏰'
    }[result.status] || '❓';

    console.log(`${statusIcon} ${test.title} (${result.duration}ms)`);
  }

  onEnd(result) {
    const duration = Date.now() - this.startTime;

    // Generate HTML report
    const html = this.generateHtmlReport(result);

    // Write report to file
    const fs = require('fs');
    fs.writeFileSync(this.options.outputFile, html);

    // Console summary
    const passed = this.results.filter(r => r.status === 'passed').length;
    const failed = this.results.filter(r => r.status === 'failed').length;

    console.log('\n=== Test Execution Summary ===');
    console.log(`Total: ${this.results.length}`);
    console.log(`Passed: ${passed}`);
    console.log(`Failed: ${failed}`);
    console.log(`Duration: ${duration}ms`);
    console.log(`Report: ${this.options.outputFile}`);
  }

  generateHtmlReport(result) {
    return `
    <!DOCTYPE html>
    <html>
    <head>
      <title>Playwright Test Report</title>
      <style>
        body { font-family: Arial, sans-serif; margin: 20px; }
        .summary { background: #f5f5f5; padding: 20px; border-radius: 5px; }
        .passed { color: green; }
        .failed { color: red; }
        .test-row:hover { background: #f9f9f9; }
        table { width: 100%; border-collapse: collapse; }
        th, td { padding: 10px; border-bottom: 1px solid #ddd; }
      </style>
    </head>
    <body>
      <h1>Playwright Test Report</h1>
      <div class="summary">
        <h2>Summary</h2>
        <p>Total Tests: ${this.results.length}</p>
        <p>Passed: ${this.results.filter(r => r.status === 'passed').length}</p>
        <p>Failed: ${this.results.filter(r => r.status === 'failed').length}</p>
        <p>Duration: ${Date.now() - this.startTime}ms</p>
      </div>
      <h2>Test Details</h2>
      <table>
        <thead>
          <tr>
            <th>Test</th>
            <th>Status</th>
            <th>Duration</th>
            <th>Errors</th>
          </tr>
        </thead>
        <tbody>
          ${this.results.map(r => `
            <tr class="test-row">
              <td>${r.test}</td>
              <td class="${r.status}">${r.status}</td>
              <td>${r.duration}ms</td>
              <td>${r.errors ? r.errors.map(e => e.message).join('<br>') : ''}</td>
            </tr>
          `).join('')}
        </tbody>
      </table>
    </body>
    </html>
    `;
  }
}

module.exports = CustomReporter;

