class ShadowDOMHandler {

    // Selenium - Java
    public WebElement findInShadowDOM(WebDriver driver, String shadowHostSelector, String elementSelector) {
        WebElement shadowHost = driver.findElement(By.cssSelector(shadowHostSelector));

        // Get shadow root
        JavascriptExecutor js = (JavascriptExecutor) driver;
        WebElement shadowRoot = (WebElement) js.executeScript(
            "return arguments[0].shadowRoot", shadowHost
        );

        // Find element within shadow DOM
        return shadowRoot.findElement(By.cssSelector(elementSelector));
    }

    // Playwright - Built-in support
    async findInShadowDOMPlaywright(page, shadowHostSelector, elementSelector) {
        // Playwright has built-in shadow DOM support
        return page.locator(`${shadowHostSelector} >>> ${elementSelector}`);
        // OR
        return page.locator(shadowHostSelector).locator('..').locator(elementSelector);
    }

    // Cypress - Custom command
    Cypress.Commands.add('findInShadowDOM', { prevSubject: 'element' }, (subject, elementSelector) => {
        return cy.wrap(subject)
            .shadow()
            .find(elementSelector);
    });
}

