class PlaywrightWindowManager {

    async handleMultipleWindows(page) {
        // Listen for new pages (windows/tabs)
        const [newPage] = await Promise.all([
            page.context().waitForEvent('page'),
            page.click('a[target="_blank"]') // Click link that opens new window
        ]);

        await newPage.waitForLoadState();

        // Interact with new page
        await newPage.fill('#search', 'Playwright');
        await newPage.click('#submit');

        // Take screenshot of new page
        await newPage.screenshot({ path: 'new-window.png' });

        // Close new page
        await newPage.close();

        // Continue with original page
        await page.bringToFront();
    }

    async handlePopupWindows(page) {
        // Handle popup window (different from new tab)
        const [popup] = await Promise.all([
            page.waitForEvent('popup'),
            page.click('button#open-popup')
        ]);

        // Popup windows often have specific features
        console.log('Popup URL:', await popup.url());
        console.log('Popup title:', await popup.title());

        // Fill form in popup
        await popup.fill('#popup-input', 'Test data');
        await popup.click('#popup-submit');

        // Wait for popup to close
        await popup.waitForEvent('close');

        // Or close it manually
        // await popup.close();
    }

    async manageMultipleContexts(browser) {
        // Create separate browser contexts (isolated sessions)
        const context1 = await browser.newContext();
        const context2 = await browser.newContext();

        const page1 = await context1.newPage();
        const page2 = await context2.newPage();

        // Each context has isolated cookies, storage, etc.
        await page1.goto('https://example.com');
        await page2.goto('https://example.com');

        // They can operate independently
        await page1.fill('#input1', 'Context 1 data');
        await page2.fill('#input1', 'Context 2 data');

        // Cleanup
        await context1.close();
        await context2.close();
    }
}

