import org.openqa.selenium.*;
import org.openqa.selenium.support.ui.*;
import java.time.Duration;

public class DialogHandler {
    private WebDriver driver;
    private WebDriverWait wait;

    public DialogHandler(WebDriver driver) {
        this.driver = driver;
        this.wait = new WebDriverWait(driver, Duration.ofSeconds(10));
    }

    /**
     * Handle alert dialog
     */
    public String handleAlert(boolean accept, String expectedText) {
        try {
            // Wait for alert to appear
            Alert alert = wait.until(ExpectedConditions.alertIsPresent());

            // Get alert text
            String alertText = alert.getText();
            System.out.println("Alert text: " + alertText);

            // Verify expected text if provided
            if (expectedText != null) {
                if (!alertText.contains(expectedText)) {
                    throw new AssertionError(
                        "Expected alert text to contain: " + expectedText + 
                        " but got: " + alertText
                    );
                }
            }

            // Handle alert
            if (accept) {
                alert.accept();
                System.out.println("Alert accepted");
            } else {
                alert.dismiss();
                System.out.println("Alert dismissed");
            }

            return alertText;

        } catch (TimeoutException e) {
            throw new RuntimeException("Alert did not appear within timeout", e);
        }
    }

    /**
     * Handle confirm dialog
     */
    public boolean handleConfirm(boolean accept) {
        String alertText = handleAlert(accept, null);

        // Return what would have been returned by confirm()
        return accept;
    }

    /**
     * Handle prompt dialog
     */
    public String handlePrompt(boolean accept, String inputText) {
        try {
            Alert alert = wait.until(ExpectedConditions.alertIsPresent());

            if (inputText != null) {
                alert.sendKeys(inputText);
            }

            if (accept) {
                alert.accept();
                return inputText;
            } else {
                alert.dismiss();
                return null;
            }

        } catch (TimeoutException e) {
            throw new RuntimeException("Prompt did not appear", e);
        }
    }

    /**
     * Handle beforeunload dialog
     */
    public void handleBeforeUnload(boolean leavePage) {
        // Beforeunload is tricky - browser may not show dialog in automation
        // Best approach: avoid triggering beforeunload in tests
        // Or use JavaScript to override onbeforeunload

        if (leavePage) {
            // Accept leaving page
            driver.switchTo().alert().accept();
        } else {
            // Stay on page
            driver.switchTo().alert().dismiss();
        }
    }

    /**
     * Handle HTTP authentication
     */
    public void handleAuthentication(String username, String password) {
        // Method 1: Include credentials in URL
        String url = driver.getCurrentUrl();
        String protocol = url.substring(0, url.indexOf("://") + 3);
        String host = url.substring(protocol.length());

        String authUrl = protocol + username + ":" + password + "@" + host;
        driver.get(authUrl);

        // Method 2: Use AutoIT/Robot for native dialog (not recommended)
        // Method 3: Configure browser to auto-fill (Chrome options)
    }

    /**
     * Mock dialog for testing
     */
    public void mockDialog(String type, String message) {
        // Inject JavaScript to mock dialog behavior
        String script = "
            window.originalAlert = window.alert;
            window.alert = function(msg) {
                window.lastAlertMessage = msg;
                console.log('Mock alert: ' + msg);
                return;
            };

            window.originalConfirm = window.confirm;
            window.confirm = function(msg) {
                window.lastConfirmMessage = msg;
                console.log('Mock confirm: ' + msg);
                return true; // Or false based on test
            };

            window.originalPrompt = window.prompt;
            window.prompt = function(msg, defaultValue) {
                window.lastPromptMessage = msg;
                console.log('Mock prompt: ' + msg);
                return 'mocked-input'; // Or null for cancel
            };
        ";

        ((JavascriptExecutor) driver).executeScript(script);
    }
}

