class PerformanceTester {
  constructor(page) {
    this.page = page;
    this.metrics = {};
  }

  async measurePageLoad(url) {
    // Start performance measurement
    await this.page.goto(url, { waitUntil: 'networkidle' });

    // Get navigation timing
    const navigationTiming = await this.page.evaluate(() => {
      const [navigationEntry] = performance.getEntriesByType('navigation');
      return {
        TTFB: navigationEntry.responseStart - navigationEntry.requestStart,
        FCP: navigationEntry.domContentLoadedEventEnd - navigationEntry.fetchStart,
        DOMComplete: navigationEntry.domComplete,
        LoadTime: navigationEntry.loadEventEnd
      };
    });

    // Get Core Web Vitals using web-vitals library
    await this.page.addScriptTag({ url: 'https://unpkg.com/web-vitals' });
    const webVitals = await this.page.evaluate(async () => {
      return new Promise(resolve => {
        const vitals = {};
        require('web-vitals').getLCP(vital => vitals.LCP = vital.value);
        require('web-vitals').getFID(vital => vitals.FID = vital.value);
        require('web-vitals').getCLS(vital => vitals.CLS = vital.value);
        setTimeout(() => resolve(vitals), 1000);
      });
    });

    // Get resource timing
    const resourceMetrics = await this.page.evaluate(() => {
      const resources = performance.getEntriesByType('resource');
      return {
        totalRequests: resources.length,
        totalSize: resources.reduce((sum, r) => sum + (r.transferSize || 0), 0),
        imageCount: resources.filter(r => r.initiatorType === 'img').length,
        scriptCount: resources.filter(r => r.initiatorType === 'script').length,
        cssCount: resources.filter(r => r.initiatorType === 'css').length
      };
    });

    this.metrics = {
      ...navigationTiming,
      ...webVitals,
      ...resourceMetrics,
      timestamp: new Date().toISOString()
    };

    return this.metrics;
  }

  async simulateNetworkConditions(condition) {
    const conditions = {
      '3g': { download: 750, upload: 250, latency: 100 },
      '4g': { download: 4000, upload: 3000, latency: 20 },
      'slow-3g': { download: 500, upload: 500, latency: 400 }
    };

    const client = await this.page.context().newCDPSession(this.page);
    await client.send('Network.emulateNetworkConditions', {
      offline: false,
      downloadThroughput: conditions[condition].download * 1024,
      uploadThroughput: conditions[condition].upload * 1024,
      latency: conditions[condition].latency
    });
  }

  async takePerformanceTrace(name) {
    // Start tracing
    await this.page.context().tracing.start({
      screenshots: true,
      snapshots: true
    });

    // Perform actions
    await this.page.goto('https://example.com');
    await this.page.click('#submit-button');

    // Stop tracing and save
    await this.page.context().tracing.stop({
      path: `traces/${name}.zip`
    });
  }

  generatePerformanceReport() {
    const report = {
      summary: {
        score: this.calculatePerformanceScore(),
        grade: this.calculatePerformanceGrade(),
        recommendations: this.generateRecommendations()
      },
      detailedMetrics: this.metrics,
      thresholds: {
        LCP: { good: 2500, needsImprovement: 4000 },
        FID: { good: 100, needsImprovement: 300 },
        CLS: { good: 0.1, needsImprovement: 0.25 }
      }
    };

    return report;
  }

  calculatePerformanceScore() {
    let score = 100;

    // Deduct points based on metrics
    if (this.metrics.LCP > 2500) score -= 30;
    if (this.metrics.FID > 100) score -= 30;
    if (this.metrics.CLS > 0.1) score -= 20;
    if (this.metrics.TTFB > 600) score -= 10;

    return Math.max(0, score);
  }

  calculatePerformanceGrade() {
    const score = this.calculatePerformanceScore();
    if (score >= 90) return 'A';
    if (score >= 80) return 'B';
    if (score >= 70) return 'C';
    if (score >= 60) return 'D';
    return 'F';
  }

  generateRecommendations() {
    const recommendations = [];

    if (this.metrics.LCP > 2500) {
      recommendations.push('Optimize LCP: Compress images, use next-gen formats, implement lazy loading');
    }

    if (this.metrics.FID > 100) {
      recommendations.push('Reduce FID: Minimize JavaScript execution, break up long tasks, use web workers');
    }

    if (this.metrics.CLS > 0.1) {
      recommendations.push('Improve CLS: Specify image dimensions, reserve space for ads/embeds, avoid sudden layout shifts');
    }

    if (this.metrics.TTFB > 600) {
      recommendations.push('Improve TTFB: Use CDN, optimize server response time, enable caching');
    }

    return recommendations;
  }
}

