const lighthouse = require('lighthouse');
const chromeLauncher = require('chrome-launcher');
const fs = require('fs');

async function runLighthouseAudit(url, options = {}) {
  // Launch Chrome
  const chrome = await chromeLauncher.launch({
    chromeFlags: ['--headless', '--no-sandbox'],
    ...options.chromeFlags
  });

  // Lighthouse configuration
  const config = {
    extends: 'lighthouse:default',
    settings: {
      onlyCategories: ['performance', 'accessibility', 'best-practices', 'seo'],
      throttling: options.throttling || {
        rttMs: 150,
        throughputKbps: 1638.4,
        cpuSlowdownMultiplier: 4,
        requestLatencyMs: 150 * 3.75,
        downloadThroughputKbps: 1638.4,
        uploadThroughputKbps: 675
      }
    }
  };

  // Run Lighthouse
  const runnerResult = await lighthouse(url, {
    port: chrome.port,
    output: 'json',
    ...config
  });

  // Close Chrome
  await chrome.kill();

  // Process results
  const report = {
    url: runnerResult.lhr.finalUrl,
    fetchTime: runnerResult.lhr.fetchTime,
    categories: {},
    audits: {},
    metrics: {}
  };

  // Extract category scores
  Object.values(runnerResult.lhr.categories).forEach(category => {
    report.categories[category.id] = {
      score: category.score * 100,
      title: category.title,
      description: category.description
    };
  });

  // Extract key metrics
  const metrics = ['first-contentful-paint', 'largest-contentful-paint', 
                   'cumulative-layout-shift', 'total-blocking-time', 'speed-index'];

  metrics.forEach(metricId => {
    const audit = runnerResult.lhr.audits[metricId];
    if (audit) {
      report.metrics[metricId] = {
        score: audit.score * 100,
        numericValue: audit.numericValue,
        displayValue: audit.displayValue,
        explanation: audit.explanation
      };
    }
  });

  // Generate recommendations
  report.recommendations = Object.values(runnerResult.lhr.audits)
    .filter(audit => audit.score < 0.9)
    .map(audit => ({
      id: audit.id,
      title: audit.title,
      description: audit.description,
      score: audit.score * 100,
      details: audit.details
    }));

  // Save report
  if (options.outputPath) {
    fs.writeFileSync(
      options.outputPath,
      JSON.stringify(report, null, 2)
    );
  }

  return report;
}

// Batch testing multiple URLs
async function runPerformanceBatch(urls, options = {}) {
  const results = [];

  for (const url of urls) {
    console.log(`Testing: ${url}`);

    try {
      const result = await runLighthouseAudit(url, options);
      results.push({
        url,
        success: true,
        data: result
      });
    } catch (error) {
      results.push({
        url,
        success: false,
        error: error.message
      });
    }

    // Delay between tests
    if (options.delayBetweenTests) {
      await new Promise(resolve => setTimeout(resolve, options.delayBetweenTests));
    }
  }

  // Generate summary report
  const summary = {
    totalTests: results.length,
    successfulTests: results.filter(r => r.success).length,
    averagePerformanceScore: results
      .filter(r => r.success)
      .reduce((sum, r) => sum + r.data.categories.performance.score, 0) / results.length,
    failingUrls: results
      .filter(r => r.success && r.data.categories.performance.score < 80)
      .map(r => r.url),
    recommendations: results
      .filter(r => r.success)
      .flatMap(r => r.data.recommendations)
      .slice(0, 10) // Top 10 recommendations
  };

  return { results, summary };
}

