// Performance budget checker
// check-performance-budget.js
const fs = require('fs');
const path = require('path');

function checkPerformanceBudget() {
  const reportsDir = '.lighthouseci';
  const files = fs.readdirSync(reportsDir)
    .filter(file => file.endsWith('.report.json'));

  const violations = [];

  files.forEach(file => {
    const report = JSON.parse(
      fs.readFileSync(path.join(reportsDir, file), 'utf8')
    );

    const url = report.finalUrl;
    const performanceScore = report.categories.performance.score * 100;

    // Check against budget
    if (performanceScore < 85) {
      violations.push({
        url,
        score: performanceScore,
        required: 85,
        metrics: {
          LCP: report.audits['largest-contentful-paint'].numericValue,
          CLS: report.audits['cumulative-layout-shift'].numericValue,
          TBT: report.audits['total-blocking-time'].numericValue
        }
      });
    }
  });

  if (violations.length > 0) {
    console.error('Performance budget violations:');
    violations.forEach(v => {
      console.error(`\n${v.url}:`);
      console.error(`  Score: ${v.score.toFixed(1)} (required: ${v.required})`);
      console.error(`  LCP: ${v.metrics.LCP}ms`);
      console.error(`  CLS: ${v.metrics.CLS}`);
      console.error(`  TBT: ${v.metrics.TBT}ms`);
    });
    process.exit(1);
  }

  console.log('All pages meet performance budget!');
}

checkPerformanceBudget();

const axios = require('axios');
const fs = require('fs');

class WebPageTestAPI {
  constructor(apiKey) {
    this.apiKey = apiKey || process.env.WEBPAGETEST_API_KEY;
    this.baseUrl = 'https://www.webpagetest.org';
  }

  async runTest(url, options = {}) {
    const params = new URLSearchParams({
      k: this.apiKey,
      url,
      f: 'json',
      runs: options.runs || 3,
      location: options.location || 'Dulles:Chrome',
      connectivity: options.connectivity || 'Cable',
      firstViewOnly: options.firstViewOnly || false,
      video: options.video || true,
      lighthouse: options.lighthouse || true,
      ...options.params
    });

    try {
      // Submit test
      const response = await axios.get(`${this.baseUrl}/runtest.php?${params}`);

      if (response.data.statusCode !== 200) {
        throw new Error(`Test submission failed: ${response.data.statusText}`);
      }

      const testId = response.data.data.testId;
      console.log(`Test submitted: ${testId}`);

      // Poll for results
      return await this.pollResults(testId, options.pollInterval || 5000);

    } catch (error) {
      throw new Error(`WebPageTest API error: ${error.message}`);
    }
  }

  async pollResults(testId, interval) {
    let attempts = 0;
    const maxAttempts = 60; // 5 minutes maximum

    while (attempts < maxAttempts) {
      attempts++;

      try {
        const response = await axios.get(
          `${this.baseUrl}/jsonResult.php?test=${testId}`
        );

        if (response.data.statusCode === 200) {
          console.log(`Test completed (attempt ${attempts})`);
          return this.processResults(response.data);
        } else if (response.data.statusCode === 100) {
          // Still waiting
          console.log(`Waiting for results... (${attempts}/${maxAttempts})`);
          await new Promise(resolve => setTimeout(resolve, interval));
        } else {
          throw new Error(`Test failed: ${response.data.statusText}`);
        }

      } catch (error) {
        console.error(`Polling error: ${error.message}`);
        await new Promise(resolve => setTimeout(resolve, interval));
      }
    }

    throw new Error('Test timed out after maximum attempts');
  }

  processResults(data) {
    const result = {
      url: data.data.url,
      summary: {
        loadTime: data.data.average.firstView.loadTime,
        firstByte: data.data.average.firstView.TTFB,
        startRender: data.data.average.firstView.render,
        speedIndex: data.data.average.firstView.SpeedIndex,
        visualComplete: data.data.average.firstView.visualComplete,
        fullyLoaded: data.data.average.firstView.fullyLoaded
      },
      metrics: {},
      recommendations: []
    };

    // Core Web Vitals
    if (data.data.lighthouse) {
      const lh = data.data.lighthouse;
      result.metrics = {
        LCP: lh.audits['largest-contentful-paint']?.numericValue,
        CLS: lh.audits['cumulative-layout-shift']?.numericValue,
        TBT: lh.audits['total-blocking-time']?.numericValue,
        FCP: lh.audits['first-contentful-paint']?.numericValue
      };
    }

    // Generate recommendations
    if (result.summary.loadTime > 3000) {
      result.recommendations.push('Load time exceeds 3 seconds - optimize resource loading');
    }

    if (result.summary.firstByte > 600) {
      result.recommendations.push('TTFB is high - improve server response time');
    }

    if (result.metrics.LCP > 2500) {
      result.recommendations.push('LCP exceeds 2.5s - optimize largest contentful paint');
    }

    return result;
  }

  async runBatchTests(urls, options = {}) {
    const results = [];
    const concurrency = options.concurrency || 2;

    // Process URLs in batches
    for (let i = 0; i < urls.length; i += concurrency) {
      const batch = urls.slice(i, i + concurrency);
      const batchPromises = batch.map(url => this.runTest(url, options));

      const batchResults = await Promise.allSettled(batchPromises);

      batchResults.forEach((result, index) => {
        if (result.status === 'fulfilled') {
          results.push({
            url: batch[index],
            success: true,
            data: result.value
          });
        } else {
          results.push({
            url: batch[index],
            success: false,
            error: result.reason.message
          });
        }
      });

      // Delay between batches
      if (options.delayBetweenBatches) {
        await new Promise(resolve => setTimeout(resolve, options.delayBetweenBatches));
      }
    }

    return results;
  }
}

