const puppeteer = require('puppeteer');
const fs = require('fs');
const path = require('path');

class CustomPerformanceMonitor {
  constructor() {
    this.results = [];
    this.browser = null;
    this.page = null;
  }

  async initialize() {
    this.browser = await puppeteer.launch({
      headless: 'new',
      args: [
        '--no-sandbox',
        '--disable-setuid-sandbox',
        '--disable-dev-shm-usage'
      ]
    });

    this.page = await this.browser.newPage();

    // Enable performance metrics
    await this.page.setCacheEnabled(false);

    // Set viewport
    await this.page.setViewport({
      width: 1920,
      height: 1080,
      deviceScaleFactor: 1
    });
  }

  async measurePerformance(url, options = {}) {
    console.log(`Measuring performance for: ${url}`);

    // Enable performance logging
    await this.page.setRequestInterception(true);
    this.page.on('request', request => {
      request.continue();
    });

    // Start tracing
    await this.page.tracing.start({
      path: options.tracePath || `trace-${Date.now()}.json`,
      screenshots: true,
      categories: ['devtools.timeline', 'disabled-by-default-devtools.screenshot']
    });

    // Navigate to URL
    const startTime = Date.now();
    const response = await this.page.goto(url, {
      waitUntil: ['load', 'networkidle0'],
      timeout: 30000
    });
    const navigationTime = Date.now() - startTime;

    // Wait for additional stability
    await this.page.waitForTimeout(2000);

    // Stop tracing
    await this.page.tracing.stop();

    // Collect metrics
    const metrics = await this.collectMetrics();
    metrics.navigationTime = navigationTime;
    metrics.url = url;
    metrics.timestamp = new Date().toISOString();

    // Simulate user interaction
    if (options.simulateInteraction) {
      const interactionMetrics = await this.simulateUserInteraction();
      Object.assign(metrics, interactionMetrics);
    }

    // Network throttling simulation
    if (options.simulateSlowNetwork) {
      const slowNetworkMetrics = await this.testWithSlowNetwork(url);
      metrics.slowNetwork = slowNetworkMetrics;
    }

    this.results.push(metrics);
    return metrics;
  }

  async collectMetrics() {
    const metrics = await this.page.evaluate(() => {
      // Navigation Timing API
      const navigation = performance.getEntriesByType('navigation')[0];

      // Resource Timing API
      const resources = performance.getEntriesByType('resource');

      // User Timing API (custom metrics)
      const marks = performance.getEntriesByType('mark');
      const measures = performance.getEntriesByType('measure');

      return {
        // Core timing metrics
        timing: {
          domainLookupStart: navigation.domainLookupStart,
          domainLookupEnd: navigation.domainLookupEnd,
          connectStart: navigation.connectStart,
          connectEnd: navigation.connectEnd,
          requestStart: navigation.requestStart,
          responseStart: navigation.responseStart,
          responseEnd: navigation.responseEnd,
          domInteractive: navigation.domInteractive,
          domContentLoaded: navigation.domContentLoadedEventEnd,
          loadEventStart: navigation.loadEventStart,
          loadEventEnd: navigation.loadEventEnd
        },

        // Custom metrics
        custom: {
          timeToFirstByte: navigation.responseStart - navigation.requestStart,
          domReadyTime: navigation.domContentLoadedEventEnd - navigation.fetchStart,
          pageLoadTime: navigation.loadEventEnd - navigation.fetchStart
        },

        // Resource metrics
        resources: {
          count: resources.length,
          totalSize: resources.reduce((sum, r) => sum + (r.transferSize || 0), 0),
          byType: {
            script: resources.filter(r => r.initiatorType === 'script').length,
            css: resources.filter(r => r.initiatorType === 'css').length,
            image: resources.filter(r => r.initiatorType === 'img').length,
            font: resources.filter(r => r.initiatorType === 'font').length,
            other: resources.filter(r => !['script', 'css', 'img', 'font'].includes(r.initiatorType)).length
          }
        },

        // Memory usage (if available)
        memory: performance.memory ? {
          usedJSHeapSize: performance.memory.usedJSHeapSize,
          totalJSHeapSize: performance.memory.totalJSHeapSize,
          jsHeapSizeLimit: performance.memory.jsHeapSizeLimit
        } : null
      };
    });

    // Get additional browser metrics
    const performanceMetrics = await this.page.metrics();
    metrics.browser = {
      tasks: performanceMetrics.Tasks,
      jsHeapUsedSize: performanceMetrics.JSHeapUsedSize,
      jsHeapTotalSize: performanceMetrics.JSHeapTotalSize,
      nodes: performanceMetrics.Nodes,
      layoutCount: performanceMetrics.LayoutCount,
      recalcStyleCount: performanceMetrics.RecalcStyleCount
    };

    return metrics;
  }

  async simulateUserInteraction() {
    const interactionMetrics = {
      clickResponseTime: null,
      scrollPerformance: null,
      inputLatency: null
    };

    // Measure click response time
    const clickStart = Date.now();
    await this.page.click('body');
    interactionMetrics.clickResponseTime = Date.now() - clickStart;

    // Measure scroll performance
    const scrollStart = Date.now();
    await this.page.evaluate(() => {
      window.scrollTo(0, 1000);
    });
    await this.page.waitForTimeout(100);
    interactionMetrics.scrollPerformance = Date.now() - scrollStart;

    // Measure input latency
    const inputStart = Date.now();
    await this.page.type('body', 'test');
    interactionMetrics.inputLatency = Date.now() - inputStart;

    return interactionMetrics;
  }

  async testWithSlowNetwork(url) {
    // Enable network throttling
    const client = await this.page.target().createCDPSession();
    await client.send('Network.emulateNetworkConditions', {
      offline: false,
      downloadThroughput: 1.5 * 1024 * 1024 / 8, // 1.5 Mbps
      uploadThroughput: 0.75 * 1024 * 1024 / 8, // 0.75 Mbps
      latency: 150
    });

    // Clear cache
    await this.page.setCacheEnabled(false);

    // Measure performance
    const startTime = Date.now();
    await this.page.goto(url, { waitUntil: 'load' });
    const loadTime = Date.now() - startTime;

    // Disable throttling
    await client.send('Network.emulateNetworkConditions', {
      offline: false,
      downloadThroughput: -1,
      uploadThroughput: -1,
      latency: 0
    });

    return { slowNetworkLoadTime: loadTime };
  }

  async generateReport() {
    const report = {
      timestamp: new Date().toISOString(),
      summary: {
        totalPages: this.results.length,
        averageLoadTime: this.results.reduce((sum, r) => sum + r.navigationTime, 0) / this.results.length,
        averageTTFB: this.results.reduce((sum, r) => sum + r.custom.timeToFirstByte, 0) / this.results.length,
        averageResources: this.results.reduce((sum, r) => sum + r.resources.count, 0) / this.results.length
      },
      pages: this.results,
      recommendations: this.generateRecommendations()
    };

    return report;
  }

  generateRecommendations() {
    const recommendations = [];

    this.results.forEach(result => {
      if (result.custom.timeToFirstByte > 600) {
        recommendations.push({
          page: result.url,
          issue: 'High Time to First Byte (> 600ms)',
          suggestion: 'Optimize server response time, use CDN, enable caching'
        });
      }

      if (result.resources.count > 100) {
        recommendations.push({
          page: result.url,
          issue: 'Too many resources (> 100 requests)',
          suggestion: 'Combine CSS/JS files, use sprites, lazy load non-critical resources'
        });
      }

      if (result.resources.totalSize > 5 * 1024 * 1024) { // 5MB
        recommendations.push({
          page: result.url,
          issue: 'Large page size (> 5MB)',
          suggestion: 'Compress images, use modern formats (WebP, AVIF), remove unused code'
        });
      }
    });

    return recommendations;
  }

  async close() {
    if (this.browser) {
      await this.browser.close();
    }
  }
}

// Usage example
async function runPerformanceTests() {
  const monitor = new CustomPerformanceMonitor();
  await monitor.initialize();

  try {
    const urls = [
      'https://example.com',
      'https://example.com/products',
      'https://example.com/about'
    ];

    for (const url of urls) {
      await monitor.measurePerformance(url, {
        simulateInteraction: true,
        simulateSlowNetwork: true
      });

      // Delay between tests
      await new Promise(resolve => setTimeout(resolve, 3000));
    }

    const report = await monitor.generateReport();

    // Save report
    fs.writeFileSync(
      'performance-report.json',
      JSON.stringify(report, null, 2)
    );

    console.log('Performance report generated');
    console.log('Summary:', report.summary);

    // Check against performance budget
    if (report.summary.averageLoadTime > 3000) {
      console.error('Performance budget violated: Average load time > 3s');
      process.exit(1);
    }

  } finally {
    await monitor.close();
  }
}

