                        --target=${env.BASE_URL} \
                        --scan-type=full \
                        --output-format=json,html
                    '''

                    // Run dependency vulnerability scan
                    sh 'npm audit --audit-level=high'
                }
            }
        }

        // Stage 8: Deployment
        stage('Deploy') {
            when {
                expression {
                    params.ENVIRONMENT == 'production' && 
                    currentBuild.result == 'SUCCESS'
                }
            }
            steps {
                script {
                    // Determine deployment strategy
                    if (params.ENVIRONMENT == 'production') {
                        // Blue-green deployment
                        sh '''
                        # Deploy to blue environment
                        kubectl apply -f kubernetes/blue-deployment.yaml

                        # Run smoke tests on blue
                        npm run test:smoke -- --url=http://blue.example.com

                        # Switch traffic if smoke tests pass
                        kubectl apply -f kubernetes/switch-traffic.yaml

                        # Run post-deployment tests
                        npm run test:post-deploy -- --url=${env.BASE_URL}
                        '''
                    } else {
                        // Regular deployment
                        sh '''
                        kubectl apply -f kubernetes/${params.ENVIRONMENT}.yaml
                        '''
                    }
                }
            }
            post {
                success {
                    script {
                        // Tag successful deployment
                        sh '''
                        git tag -a "deploy-${params.ENVIRONMENT}-${env.BUILD_NUMBER}" -m "Deployed to ${params.ENVIRONMENT}"
                        git push origin "deploy-${params.ENVIRONMENT}-${env.BUILD_NUMBER}"
                        '''
                    }
                }
                failure {
                    script {
                        // Rollback on failure
                        if (params.ENVIRONMENT == 'production') {
                            sh '''
                            kubectl apply -f kubernetes/rollback.yaml
                            '''
                        }
                    }
                }
            }
        }
    }

    post {
        // Post-build actions
        always {
            script {
                // Cleanup workspace
                cleanWs()

                // Update build description
                currentBuild.description = "${params.ENVIRONMENT} - ${params.BROWSER}"

                // Set build display name
                currentBuild.displayName = "#${env.BUILD_NUMBER} - ${params.ENVIRONMENT}"
            }
        }

        success {
            script {
                // Success notifications
                if (params.ENVIRONMENT == 'production') {
                    // Send success notification to Slack
                    slackSend(
                        color: 'good',
                        message: "✅ Build #${env.BUILD_NUMBER} passed for ${params.ENVIRONMENT} environment\n" +
                                "Branch: ${env.GIT_BRANCH}\n" +
                                "Tests: All passed\n" +
                                "Deployment: Successful\n" +
                                "<${env.BUILD_URL}|View Build>",
                        channel: '#deployments'
                    )
                }
            }
        }

        failure {
            script {
                // Failure notifications
                def testFailures = ""

                // Check for specific test failures
                try {
                    def allureReport = readFile('src/allure-report/data/test-cases.json')
                    def testCases = readJSON(text: allureReport)
                    def failedTests = testCases.findAll { it.status == 'failed' }

                    if (failedTests) {
                        testFailures = "\nFailed tests:\n"
                        failedTests.take(5).each { test ->
                            testFailures += "• ${test.name}\n"
                        }
                        if (failedTests.size() > 5) {
                            testFailures += "... and ${failedTests.size() - 5} more\n"
                        }
                    }
                } catch (Exception e) {
                    // If can't read allure report, use generic message
                    testFailures = "\n(Detailed test failure information not available)"
                }

                // Send failure notification
                slackSend(
                    color: 'danger',
                    message: "❌ Build #${env.BUILD_NUMBER} failed for ${params.ENVIRONMENT} environment\n" +
                            "Branch: ${env.GIT_BRANCH}\n" +
                            "${testFailures}" +
                            "<${env.BUILD_URL}|View Build>\n" +
                            "<${env.BUILD_URL}Allure_Report/|View Test Report>",
                    channel: '#ci-failures'
                )

                // Also notify specific teams based on failure type
                if (testFailures.contains('visual')) {
                    slackSend(
                        color: 'warning',
                        message: "🎨 Visual regression detected in build #${env.BUILD_NUMBER}\n<${env.BUILD_URL}|Review Changes>",
                        channel: '#design-team'
                    )
                }

                if (testFailures.contains('accessibility')) {
                    slackSend(
                        color: 'warning',
                        message: "♿ Accessibility issues found in build #${env.BUILD_NUMBER}\n<${env.BUILD_URL}|Review Issues>",
                        channel: '#a11y-team'
                    )
                }
            }
        }

        unstable {
            script {
                // Unstable build notifications
                slackSend(
                    color: 'warning',
                    message: "⚠️ Build #${env.BUILD_NUMBER} is unstable for ${params.ENVIRONMENT}\n" +
                            "Some tests failed but not critical\n" +
                            "<${env.BUILD_URL}|Review Tests>",
                    channel: '#ci-notifications'
                )
            }
        }

        changed {
            script {
                // Build status changed notifications
                if (currentBuild.previousBuild?.result != currentBuild.result) {
                    slackSend(
                        color: 'good',
                        message: "🔄 Build #${env.BUILD_NUMBER} status changed from ${currentBuild.previousBuild?.result} to ${currentBuild.result}\n<${env.BUILD_URL}|View Build>",
                        channel: '#ci-monitor'
                    )
                }
            }
        }
    }
}

