# Test execution script using cloud platforms
# run-cloud-tests.js
const { Builder, Capabilities } = require('selenium-webdriver');
const { Options: ChromeOptions } = require('selenium-webdriver/chrome');
const { Options: FirefoxOptions } = require('selenium-webdriver/firefox');
const config = require('./browserstack-integration.yml');

class CloudTestRunner {
  constructor(platform = 'browserstack') {
    this.platform = platform;
    this.config = this.loadConfig(platform);
    this.results = [];
  }

  loadConfig(platform) {
    switch (platform) {
      case 'browserstack':
        return config.browserstack;
      case 'lambdatest':
        return config.lambdatest;
      case 'saucelabs':
        return config.saucelabs;
      case 'crossbrowsertesting':
        return config.crossbrowsertesting;
      default:
        throw new Error(`Unknown platform: ${platform}`);
    }
  }

  async createDriver(browserConfig) {
    let capabilities;

    switch (this.platform) {
      case 'browserstack':
        capabilities = {
          'bstack:options': {
            userName: this.config.user,
            accessKey: this.config.key,
            os: browserConfig.os,
            osVersion: browserConfig.osVersion,
            browserVersion: browserConfig.browserVersion,
            projectName: this.config.project,
            buildName: this.config.build,
            sessionName: this.config.name,
            consoleLogs: 'errors',
            networkLogs: true,
            video: true,
            ...this.config.capabilities
          },
          browserName: browserConfig.browserName
        };
        break;

      case 'lambdatest':
        capabilities = {
          'LT:Options': {
            username: this.config.user,
            accessKey: this.config.key,
            platformName: browserConfig.os,
            browserVersion: browserConfig.browserVersion,
            project: this.config.project,
            build: this.config.build,
            name: this.config.name,
            video: true,
            network: true,
            console: true,
            visual: true,
            ...this.config.capabilities
          },
          browserName: browserConfig.browserName
        };
        break;
    }

    let driver;

    switch (this.platform) {
      case 'browserstack':
        driver = await new Builder()
          .usingServer('https://hub.browserstack.com/wd/hub')
          .withCapabilities(capabilities)
          .build();
        break;

      case 'lambdatest':
        driver = await new Builder()
          .usingServer(`https://${this.config.user}:${this.config.key}@${this.config.gridUrl}`)
          .withCapabilities(capabilities)
          .build();
        break;
    }

    return driver;
  }

  async runTestSuite(testUrl, browsers = this.config.browsers) {
    console.log(`Running tests on ${this.platform} with ${browsers.length} browser configurations`);

    const testPromises = browsers.map(async (browserConfig, index) => {
      let driver;
      const startTime = Date.now();

      try {
        console.log(`Starting test ${index + 1}/${browsers.length}: ${browserConfig.browserName} on ${browserConfig.os}`);

        // Create driver
        driver = await this.createDriver(browserConfig);

        // Navigate to test URL
        await driver.get(testUrl);

        // Execute test logic (this would be your actual test)
        const title = await driver.getTitle();
        console.log(`Page title: ${title}`);

        // Take screenshot
        const screenshot = await driver.takeScreenshot();

        // Record test result
        const result = {
          browser: browserConfig.browserName,
          os: browserConfig.os,
          version: browserConfig.browserVersion,
          status: 'passed',
          duration: Date.now() - startTime,
          screenshot: screenshot.substring(0, 100) + '...' // Truncated for logging
        };

        this.results.push(result);
        console.log(`✓ Test passed on ${browserConfig.browserName}/${browserConfig.os}`);

      } catch (error) {
        console.error(`✗ Test failed on ${browserConfig.browserName}/${browserConfig.os}:`, error.message);

        const result = {
          browser: browserConfig.browserName,
          os: browserConfig.os,
          version: browserConfig.browserVersion,
          status: 'failed',
          duration: Date.now() - startTime,
          error: error.message
        };

        this.results.push(result);

      } finally {
        if (driver) {
          try {
            await driver.quit();
          } catch (quitError) {
            console.error('Error quitting driver:', quitError.message);
          }
        }
      }
    });

    // Run tests with concurrency limit
    const concurrency = this.config.parallelRuns || 5;
    for (let i = 0; i < testPromises.length; i += concurrency) {
      const batch = testPromises.slice(i, i + concurrency);
      await Promise.all(batch);
      console.log(`Completed batch ${Math.floor(i / concurrency) + 1}/${Math.ceil(testPromises.length / concurrency)}`);
    }

    return this.generateReport();
  }

  generateReport() {
    const total = this.results.length;
    const passed = this.results.filter(r => r.status === 'passed').length;
    const failed = this.results.filter(r => r.status === 'failed').length;
    const passRate = (passed / total * 100).toFixed(2);

    const report = {
      platform: this.platform,
      timestamp: new Date().toISOString(),
      summary: {
        total,
        passed,
        failed,
        passRate,
        totalDuration: this.results.reduce((sum, r) => sum + r.duration, 0)
      },
      results: this.results,
      recommendations: []
    };

    // Generate recommendations
    if (passRate < 90) {
      report.recommendations.push(`Pass rate ${passRate}% is below threshold of 90%`);
    }

    const failedBrowsers = this.results
      .filter(r => r.status === 'failed')
      .map(r => `${r.browser} ${r.version} on ${r.os}`);

    if (failedBrowsers.length > 0) {
      report.recommendations.push(`Failed browsers: ${failedBrowsers.join(', ')}`);
    }

    return report;
  }
}

// Usage example
async function main() {
  const testUrl = process.env.TEST_URL || 'https://example.com';

  // Run on multiple platforms
  const platforms = ['browserstack', 'lambdatest'];
  const allReports = [];

  for (const platform of platforms) {
    console.log(`\n=== Running tests on ${platform.toUpperCase()} ===`);

    const runner = new CloudTestRunner(platform);
    const report = await runner.runTestSuite(testUrl);

    allReports.push(report);

    console.log(`\n${platform} Report:`);
    console.log(`Pass Rate: ${report.summary.passRate}%`);
    console.log(`Total Duration: ${report.summary.totalDuration}ms`);
  }

  // Generate consolidated report
  const consolidated = {
    timestamp: new Date().toISOString(),
    testUrl,
    platforms: allReports.map(r => ({
      platform: r.platform,
      passRate: r.summary.passRate,
      totalTests: r.summary.total
    })),
    overallPassRate: allReports.reduce((sum, r) => sum + r.summary.passRate, 0) / allReports.length
  };

  console.log('\n=== Consolidated Report ===');
  console.log(JSON.stringify(consolidated, null, 2));

  // Check if any platform failed
  const failingPlatforms = allReports.filter(r => r.summary.passRate < 90);
  if (failingPlatforms.length > 0) {
    console.error('\n❌ Some platforms failed to meet pass rate threshold');
    process.exit(1);
  }

  console.log('\n✅ All platforms passed!');
}

main().catch(console.error);

// parallel-test-runner.js
const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');
const os = require('os');

class ParallelTestRunner {
  constructor(config) {
    this.config = {
      maxParallel: os.cpus().length - 1, // Leave one CPU free
      testTimeout: 60000,
      retryAttempts: 2,
      testDirectory: './tests',
      reportDirectory: './reports',
      ...config
    };

    this.testQueue = [];
    this.runningTests = new Map();
    this.completedTests = [];
    this.failedTests = [];
    this.results = {};
  }

  async discoverTests() {
    console.log('Discovering tests...');

    const testFiles = [];
    const walkDir = (dir) => {
      const files = fs.readdirSync(dir);

      files.forEach(file => {
        const filePath = path.join(dir, file);
        const stat = fs.statSync(filePath);

        if (stat.isDirectory()) {
          walkDir(filePath);
        } else if (file.endsWith('.spec.js') || file.endsWith('.test.js')) {
          testFiles.push(filePath);
        }
      });
    };

    walkDir(this.config.testDirectory);

    // Analyze test files to estimate duration
    const testsWithMetadata = testFiles.map(file => ({
      file,
      estimatedDuration: this.estimateTestDuration(file),
      priority: this.calculateTestPriority(file),
      dependencies: this.extractTestDependencies(file)
    }));

    // Sort by priority and estimated duration
    testsWithMetadata.sort((a, b) => {
      if (a.priority !== b.priority) {
        return b.priority - a.priority; // Higher priority first
      }
      return b.estimatedDuration - a.estimatedDuration; // Longer tests first
    });

    this.testQueue = testsWithMetadata;
    console.log(`Discovered ${testFiles.length} tests`);

    return testsWithMetadata;
  }

  estimateTestDuration(testFile) {
    // Read test file and estimate duration based on content
    const content = fs.readFileSync(testFile, 'utf8');

    // Simple heuristics
    let estimatedDuration = 5000; // Base duration

    // Count API calls
    const apiCalls = (content.match(/fetch\(|axios\.|request\(/g) || []).length;
    estimatedDuration += apiCalls * 1000;

    // Count UI interactions
    const uiInteractions = (content.match(/click\(|type\(|hover\(/g) || []).length;
    estimatedDuration += uiInteractions * 500;

    // Count assertions
    const assertions = (content.match(/expect\(|assert\.|should\./g) || []).length;
    estimatedDuration += assertions * 100;

    return Math.min(estimatedDuration, 30000); // Cap at 30 seconds
  }

  calculateTestPriority(testFile) {
    const content = fs.readFileSync(testFile, 'utf8').toLowerCase();
    let priority = 1; // Default priority

    // Check for priority markers
    if (content.includes('@critical') || content.includes('@smoke')) {
      priority = 5;
    } else if (content.includes('@regression')) {
      priority = 3;
    } else if (content.includes('@integration')) {
      priority = 2;
    }

    // Check if it's a core user journey
    if (content.includes('login') || content.includes('checkout') || content.includes('search')) {
      priority = Math.max(priority, 4);
    }

    return priority;
  }

  extractTestDependencies(testFile) {
    const content = fs.readFileSync(testFile, 'utf8');
    const dependencies = [];

    // Extract dependencies from require/import statements
    const requireMatches = content.match(/require\(['"]([^'"]+)['"]\)/g) || [];
    const importMatches = content.match(/from ['"]([^'"]+)['"]/g) || [];

    [...requireMatches, ...importMatches].forEach(match => {
      const dep = match.match(/['"]([^'"]+)['"]/);
      if (dep && dep[1]) {
        dependencies.push(dep[1]);
      }
    });

    return dependencies;
  }

  async runTest(test) {
    const startTime = Date.now();
    const testId = `${path.basename(test.file)}-${Date.now()}`;

    console.log(`Starting test: ${path.basename(test.file)} (estimated: ${test.estimatedDuration}ms)`);

    return new Promise((resolve, reject) => {
      const command = `npx playwright test ${test.file} --reporter=json --timeout=${this.config.testTimeout}`;

      const childProcess = exec(command, {
        env: {
          ...process.env,
          CI: 'true',
          TEST_ID: testId
        }
      });

      this.runningTests.set(testId, {
        process: childProcess,
        startTime,
        test
      });

      let stdout = '';
      let stderr = '';

      childProcess.stdout.on('data', (data) => {
        stdout += data;
      });

      childProcess.stderr.on('data', (data) => {
        stderr += data;
      });

      childProcess.on('close', (code) => {
        const duration = Date.now() - startTime;
        this.runningTests.delete(testId);

        const result = {
          testId,
          file: test.file,
          duration,
          exitCode: code,
          stdout: stdout.substring(0, 1000), // Limit size
          stderr: stderr.substring(0, 1000),
          retryCount: 0
        };

        if (code === 0) {
          console.log(`✓ Test passed: ${path.basename(test.file)} (${duration}ms)`);
          this.completedTests.push(result);
          resolve(result);
        } else {
          console.log(`✗ Test failed: ${path.basename(test.file)} (${duration}ms)`);
          this.failedTests.push(result);
          reject(result);
        }
      });

      // Timeout handling
      setTimeout(() => {
        if (childProcess && !childProcess.killed) {
          console.log(`⏰ Test timeout: ${path.basename(test.file)}`);
          childProcess.kill('SIGTERM');

          const timeoutResult = {
            testId,
            file: test.file,
            duration: this.config.testTimeout,
            exitCode: 1,
            stdout,
            stderr: 'Test timeout',
            timeout: true
          };

          this.failedTests.push(timeoutResult);
          reject(timeoutResult);
        }
      }, this.config.testTimeout);
    });
  }

  async runTests() {
    await this.discoverTests();

    console.log(`\nRunning tests with ${this.config.maxParallel} parallel workers\n`);

    while (this.testQueue.length > 0 || this.runningTests.size > 0) {
      // Start new tests if we have capacity
      while (this.runningTests.size < this.config.maxParallel && this.testQueue.length > 0) {
        const test = this.testQueue.shift();
        this.runTest(test).catch(error => {
          // Handle test failure (retry logic would go here)
          console.error(`Test failed: ${error.file}`);
        });
      }

      // Wait a bit before checking again
      await new Promise(resolve => setTimeout(resolve, 1000));

      // Log progress
      const completed = this.completedTests.length + this.failedTests.length;
      const total = completed + this.testQueue.length + this.runningTests.size;
      const progress = ((completed / total) * 100).toFixed(1);

      console.log(`Progress: ${completed}/${total} (${progress}%) | Running: ${this.runningTests.size} | Queued: ${this.testQueue.length}`);
    }

    return this.generateReport();
  }

  async runWithRetry(test, maxRetries = this.config.retryAttempts) {
    for (let attempt = 1; attempt <= maxRetries + 1; attempt++) {
      try {
        const result = await this.runTest(test);
        result.retryCount = attempt - 1;
        return result;
      } catch (error) {
        if (attempt > maxRetries) {
          error.retryCount = maxRetries;
          throw error;
        }
        console.log(`Retrying test (attempt ${attempt}/${maxRetries}): ${path.basename(test.file)}`);

        // Exponential backoff
        await new Promise(resolve => setTimeout(resolve, Math.pow(2, attempt) * 1000));
      }
    }
  }

  generateReport() {
    const totalTests = this.completedTests.length + this.failedTests.length;
    const passedTests = this.completedTests.length;
    const failedTests = this.failedTests.length;
    const passRate = totalTests > 0 ? (passedTests / totalTests * 100).toFixed(2) : 0;

    const totalDuration = [...this.completedTests, ...this.failedTests]
      .reduce((sum, test) => sum + test.duration, 0);

    const avgDuration = totalTests > 0 ? (totalDuration / totalTests).toFixed(0) : 0;

    // Group failures by type
    const failureCategories = {
      timeout: this.failedTests.filter(t => t.timeout).length,
      assertion: this.failedTests.filter(t => t.stderr.includes('AssertionError')).length,
      network: this.failedTests.filter(t => t.stderr.includes('net::') || t.stderr.includes('ECONN')).length,
      other: this.failedTests.filter(t => !t.timeout && !t.stderr.includes('AssertionError') && 
        !(t.stderr.includes('net::') || t.stderr.includes('ECONN'))).length
    };

    const report = {
      summary: {
        totalTests,
        passedTests,
        failedTests,
        passRate,
        totalDuration,
        avgDuration,
        parallelEfficiency: ((totalDuration / (this.config.maxParallel * 1000)) * 100).toFixed(2) + '%'
      },
      failures: failureCategories,
      slowestTests: [...this.completedTests, ...this.failedTests]
        .sort((a, b) => b.duration - a.duration)
        .slice(0, 10)
        .map(t => ({
          file: path.basename(t.file),
          duration: t.duration,
          status: t.exitCode === 0 ? 'passed' : 'failed'
        })),
      recommendations: []
    };

    // Generate recommendations
    if (passRate < 95) {
      report.recommendations.push(`Test pass rate is ${passRate}%, target is 95%`);
    }

    if (failureCategories.timeout > 0) {
      report.recommendations.push(`${failureCategories.timeout} tests timed out - consider increasing timeout or optimizing slow tests`);
    }

    if (failureCategories.network > 0) {
      report.recommendations.push(`${failureCategories.network} tests failed due to network issues - check API/stability`);
    }

    // Save report to file
    const reportPath = path.join(this.config.reportDirectory, `parallel-report-${Date.now()}.json`);
    fs.writeFileSync(reportPath, JSON.stringify(report, null, 2));

    console.log(`\n=== Parallel Execution Report ===`);
    console.log(`Pass Rate: ${passRate}%`);
    console.log(`Total Duration: ${totalDuration}ms`);
    console.log(`Parallel Efficiency: ${report.summary.parallelEfficiency}`);
    console.log(`Report saved to: ${reportPath}`);

    return report;
  }
}

